.kalos-dropzone {
  position: relative;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  width: 100%;
  min-width: 0;
  max-width: var(--kalos-dz-width);
  padding: 8px 8px 0;
  overflow: hidden;
  border-radius: var(--kalos-dz-radius);
  border: 1px solid var(--kalos-dz-edge);
  background: var(--kalos-dz-surface);
  box-shadow: var(--kalos-dz-shadow);
  color: var(--kalos-dz-ink);
}
.kalos-dropzone[data-variant="button"] {
  align-items: flex-start;
  gap: 12px;
  padding: 0;
  overflow: visible;
  border: 0;
  background: none;
  box-shadow: none;
}
.kalos-dropzone[data-variant="button"] .kalos-dropzone-files {
  box-sizing: border-box;
  width: 100%;
  padding-inline: 8px;
  overflow: hidden;
  border: 1px solid var(--kalos-dz-edge);
  border-radius: var(--kalos-dz-radius);
  background: var(--kalos-dz-surface);
  box-shadow: var(--kalos-dz-shadow);
}
.kalos-dropzone[data-variant="button"] .kalos-dropzone-files:has(.kalos-dropzone-list:empty) {
  display: none;
}
.kalos-dropzone-target {
  display: flex;
  width: 100%;
  min-height: 138px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 1px dashed var(--kalos-dz-dash);
  border-radius: var(--kalos-dz-inner-radius);
  background: var(--kalos-dz-inset);
  color: inherit;
  font: inherit;
  padding: 18px 10px;
  text-align: center;
  cursor: pointer;
  transition: border-color 160ms, background-color 160ms;
}
.kalos-dropzone-target:hover { background: var(--kalos-dz-hover); }
.kalos-dropzone-target[data-dragging] {
  background: var(--kalos-dz-accent-wash);
  border-color: var(--kalos-dz-accent);
}
.kalos-dropzone-target:focus-visible,
.kalos-dropzone-actions button:focus-visible {
  outline: 2px solid var(--kalos-dz-focus);
  outline-offset: 2px;
}
.kalos-dropzone-target > span { pointer-events: none; }
.kalos-dropzone-art {
  position: relative;
  display: block;
  width: 76px;
  height: 44px;
  margin-bottom: 10px;
}
.kalos-dropzone-paper,
.kalos-dropzone-upload-icon {
  position: absolute;
  top: 3px;
  left: 50%;
  display: grid;
  box-sizing: border-box;
  width: 30px;
  height: 36px;
  margin-left: -15px;
  place-content: center;
  justify-items: center;
  transition: transform var(--kalos-dz-fan-duration) var(--kalos-dz-ease), color 160ms;
}
.kalos-dropzone-paper {
  width: 38px;
  height: 38px;
  margin-left: -19px;
  color: var(--kalos-dz-file-ink);
  transform: translate(var(--paper-x), 3px) rotate(var(--paper-angle));
  transform-origin: 50% 75%;
}
.kalos-dropzone [data-tone="document"] {
  --kalos-dz-file-ink: var(--kalos-dz-danger);
  --kalos-dz-file-wash: var(--kalos-dz-document-wash);
}
.kalos-dropzone [data-tone="image"] {
  --kalos-dz-file-ink: var(--kalos-dz-image);
  --kalos-dz-file-wash: var(--kalos-dz-image-wash);
}
.kalos-dropzone [data-tone="sheet"] { --kalos-dz-file-ink: var(--kalos-dz-success); }
.kalos-dropzone [data-tone="word"] { --kalos-dz-file-ink: var(--kalos-dz-word); }
